<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
saas_require_login();
$orgId=saas_require_organization();saas_require_permission('tour.edit');$id=(int)($_GET['id']??$_POST['id']??0);$db=saas_db();if($id<=0)$id=saas_current_tour_id();
$q=$db->prepare("SELECT t.* FROM tours t INNER JOIN tour_members tm ON tm.tour_id=t.id WHERE t.id=? AND t.organization_id=? AND tm.user_id=? AND tm.status='ACTIVE' LIMIT 1");$q->execute([$id,$orgId,saas_user_id()]);$t=$q->fetch();if(!$t){http_response_code(404);exit('Tour not found.');}
$q=$db->prepare("SELECT setting_key,setting_value FROM tour_settings WHERE tour_id=? AND setting_key IN ('default_transport','banner_image')");$q->execute([$id]);$settings=[];foreach($q as $s)$settings[$s['setting_key']]=$s['setting_value'];
$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$name=trim((string)$_POST['name']);$start=trim((string)$_POST['start_date']);$end=trim((string)$_POST['end_date']);$fee=max(0,(float)$_POST['default_fee']);$desc=trim((string)$_POST['description']);$status=strtoupper(trim((string)$_POST['status']));$transport=strtoupper(trim((string)$_POST['default_transport']));$banner=trim((string)$_POST['banner_image']);if($name==='')throw new RuntimeException('Tour name is required.');if($end!==''&&$start!==''&&$end<$start)throw new RuntimeException('End date cannot be before start date.');if(!in_array($status,['DRAFT','ACTIVE','CLOSED','ARCHIVED'],true))throw new RuntimeException('Invalid status.');if(!in_array($transport,['BUS','TRAIN','LAUNCH','AIR','OTHER','NONE'],true))throw new RuntimeException('Invalid transport.');$q=$db->prepare('UPDATE tours SET name=?,start_date=?,end_date=?,default_fee=?,description=?,status=? WHERE id=? AND organization_id=?');$q->execute([$name,$start?:null,$end?:null,$fee,$desc?:null,$status,$id,$orgId]);$s=$db->prepare('INSERT INTO tour_settings(tour_id,setting_key,setting_value,value_type) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),value_type=VALUES(value_type)');$s->execute([$id,'default_transport',$transport,'STRING']);$s->execute([$id,'banner_image',$banner,'STRING']);saas_audit('tour.updated','tour',$id,json_encode(['name'=>$name,'status'=>$status],JSON_UNESCAPED_UNICODE));$ok='Tour updated.';$t['name']=$name;$t['start_date']=$start;$t['end_date']=$end;$t['default_fee']=$fee;$t['description']=$desc;$t['status']=$status;$settings['default_transport']=$transport;$settings['banner_image']=$banner;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit tour</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f5f7fb;margin:0;color:#172033}.box{max-width:820px;margin:35px auto;background:#fff;padding:28px;border-radius:18px;box-shadow:0 8px 30px #0001}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-size:13px;font-weight:700;margin:12px 0}input,select,textarea,button{width:100%;padding:11px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}textarea{min-height:100px}button{background:#155eef;color:#fff;border-color:#155eef;font-weight:800;cursor:pointer}.actions{display:flex;gap:10px;margin-top:18px}.actions a{padding:11px 14px;border:1px solid #d0d5dd;border-radius:9px}.msg{padding:11px;border-radius:9px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><main class="box"><p><a href="tours.php">← Back to tours</a></p><h1>Edit tour</h1><?php if($ok):?><div class="msg ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=saas_h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="grid"><label>Tour name<input name="name" value="<?=saas_h($t['name'])?>" required></label><label>Status<select name="status"><?php foreach(['DRAFT','ACTIVE','CLOSED','ARCHIVED'] as $s):?><option <?=$t['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="start_date" value="<?=saas_h($t['start_date']??'')?>"></label><label>End date<input type="date" name="end_date" value="<?=saas_h($t['end_date']??'')?>"></label><label>Default fee<input type="number" step="0.01" min="0" name="default_fee" value="<?=saas_h($t['default_fee'])?>"></label><label>Default transport<select name="default_transport"><?php foreach(['BUS'=>'Bus','TRAIN'=>'Train','LAUNCH'=>'Launch / Ferry','AIR'=>'Air','OTHER'=>'Other','NONE'=>'Not selected'] as $k=>$v):?><option value="<?=$k?>" <?=($settings['default_transport']??'NONE')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label style="grid-column:1/-1">Banner image URL<input name="banner_image" value="<?=saas_h($settings['banner_image']??'')?>" placeholder="https://..."></label><label style="grid-column:1/-1">Description<textarea name="description"><?=saas_h($t['description']??'')?></textarea></label></div><div class="actions"><button>Save changes</button><a href="tour_open.php?id=<?=$id?>">Open dashboard</a></div></form></main></body></html>